(4556685, 656353, 656, '<td valign="top">Feels a bit too grey and not white enough to really give a snow feel. Good subject choice.</td>', 'Feels a bit too grey and not white enough to really give a snow feel. Good subject choice.', '2008-03-12 00:47:44.000000', NULL, 1),
(4556710, 656930, 3554, '<td valign="top">Wonderful color and the blur adds to the beauty of he shot by softening everything up. Great take on the challenge.</td>', 'Wonderful color and the blur adds to the beauty of he shot by softening everything up. Great take on the challenge.', '2008-03-12 00:57:14.000000', NULL, 1),
(4556714, 656407, 3554, '<td valign="top">Wonderful gritty picture -- the blur and technical "imperfections" add a lot of punch. It makes me feel like I''m there making my way through the crowd.</td>', 'Wonderful gritty picture -- the blur and technical "imperfections" add a lot of punch. It makes me feel like I''m there making my way through the crowd.', '2008-03-12 00:58:18.000000', NULL, 1),
(4556719, 656550, 3554, '<td valign="top">Wonderful use of blur to capture the moment.</td>', 'Wonderful use of blur to capture the moment.', '2008-03-12 00:59:29.000000', NULL, 1),
(4556720, 656406, 61552, '<td valign="top">True, but not a blurry mess.</td>', 'True, but not a blurry mess.', '2008-03-12 00:59:45.000000', NULL, 1),
(4556722, 657062, 3554, '<td valign="top">The blur and pixelation work really well in this shot to bring the emotion of the moment to your audience.</td>', 'The blur and pixelation work really well in this shot to bring the emotion of the moment to your audience.', '2008-03-12 01:00:06.000000', NULL, 1),
(4556724, 656242, 3554, '<td valign="top">The red on gray is what I think makes this shot above average. Fits the challenge well.</td>', 'The red on gray is what I think makes this shot above average. Fits the challenge well.', '2008-03-12 01:00:42.000000', NULL, 1),
