(4558801, 656290, 89341, '<td valign="top">Nice image, keeps my attention so must be interesting!</td>', 'Nice image, keeps my attention so must be interesting!', '2008-03-12 16:56:39.000000', NULL, 1),
(4558804, 657110, 89341, '<td valign="top">Colours are good, semi chaotic and disorganised</td>', 'Colours are good, semi chaotic and disorganised', '2008-03-12 16:57:17.000000', NULL, 1),
(4558808, 657063, 30982, '<td valign="top">If I were to guess, I''d say Andre.  This is wonderful.</td>', 'If I were to guess, I''d say Andre.  This is wonderful.', '2008-03-12 16:57:59.000000', NULL, 1),
(4558811, 656005, 30982, '<td valign="top">Wonderful interpretation!</td>', 'Wonderful interpretation!', '2008-03-12 16:58:42.000000', NULL, 1),
