(4565840, 656579, 76335, '<td valign="top">Good use of negative space. Nice colors, blur and good chaotic foreground.</td>', 'Good use of negative space. Nice colors, blur and good chaotic foreground.', '2008-03-15 18:43:47.000000', NULL, 1),
(4565842, 655857, 76335, '<td valign="top">Finally! One that I like! What a bizarre challenge...</td>', 'Finally! One that I like! What a bizarre challenge...', '2008-03-15 18:45:20.000000', NULL, 1),
(4565843, 656490, 76335, '<td valign="top">Terrific effect! Blurry too!!!</td>', 'Terrific effect! Blurry too!!!', '2008-03-15 18:45:29.000000', NULL, 1),
