(4565846, 657089, 76335, '<td valign="top">Oh, that''s terrific. Best I''ve seen so far. Blurry and messy, but fun too.</td>', 'Oh, that''s terrific. Best I''ve seen so far. Blurry and messy, but fun too.', '2008-03-15 18:45:40.000000', NULL, 1),
(4565847, 657141, 76335, '<td valign="top">Very blurry and messy. Extra points for misspelling (<i>mess</i>ing up) your title.</td>', 'Very blurry and messy. Extra points for misspelling (messing up) your title.', '2008-03-15 18:45:42.000000', NULL, 1),
(4565848, 656382, 76335, '<td valign="top">My kind of image! Blurry and messy and a feast for the eyes. Nice!</td>', 'My kind of image! Blurry and messy and a feast for the eyes. Nice!', '2008-03-15 18:45:46.000000', NULL, 1),
(4565849, 656337, 76335, '<td valign="top">Good job! Blurry <i>and</i> messy. Very artistic.</td>', 'Good job! Blurry and messy. Very artistic.', '2008-03-15 18:45:51.000000', NULL, 1),
(4565850, 655811, 76335, '<td valign="top">Terrific colors and blur!</td>', 'Terrific colors and blur!', '2008-03-15 18:45:54.000000', NULL, 1),
(4565851, 656290, 76335, '<td valign="top">Excellent! Blurry and messy too. Nice colors and shapes.</td>', 'Excellent! Blurry and messy too. Nice colors and shapes.', '2008-03-15 18:45:57.000000', NULL, 1),
(4565852, 657072, 76335, '<td valign="top">Nice soft colors and "brushstrokes"...</td>', 'Nice soft colors and "brushstrokes"...', '2008-03-15 18:45:58.000000', NULL, 1),
(4565853, 657130, 76335, '<td valign="top">Terrific! The colors and framing are great. Love the title...</td>', 'Terrific! The colors and framing are great. Love the title...', '2008-03-15 18:46:03.000000', NULL, 1),
(4565854, 654996, 76335, '<td valign="top">Yes! Blurry and messy and engaging. I like the colors and the "brushstrokes."</td>', 'Yes! Blurry and messy and engaging. I like the colors and the "brushstrokes."', '2008-03-15 18:46:05.000000', NULL, 1),
(4565855, 656852, 76335, '<td valign="top">Great image! I love the bright bold etchings of light into the burry nighttime road scene.</td>', 'Great image! I love the bright bold etchings of light into the burry nighttime road scene.', '2008-03-15 18:46:07.000000', NULL, 1),
(4565856, 656659, 76335, '<td valign="top">Bright and brilliant and blurry too. Nice job!</td>', 'Bright and brilliant and blurry too. Nice job!', '2008-03-15 18:46:08.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4565857, 656396, 76335, '<td valign="top">I like the "scribbled light" effect against the blurry background. Nice!</td>', 'I like the "scribbled light" effect against the blurry background. Nice!', '2008-03-15 18:46:36.000000', NULL, 1),
(4565858, 657063, 76335, '<td valign="top">Very artistic and wonderful colors.</td>', 'Very artistic and wonderful colors.', '2008-03-15 18:46:39.000000', NULL, 1),
(4565859, 654933, 76335, '<td valign="top">Yes! This is what the challenge is about (in my opinion, at least). Nice work with the colors and light.</td>', 'Yes! This is what the challenge is about (in my opinion, at least). Nice work with the colors and light.', '2008-03-15 18:46:42.000000', NULL, 1),
(4565860, 657136, 76335, '<td valign="top">Neat idea. Nice colors and texture here and it meets the challenge well.</td>', 'Neat idea. Nice colors and texture here and it meets the challenge well.', '2008-03-15 18:46:44.000000', NULL, 1),
(4565861, 656686, 76335, '<td valign="top">This is good. Bold, overdone and unfinished ("messy" in that sense) with nice blurry colors.</td>', 'This is good. Bold, overdone and unfinished ("messy" in that sense) with nice blurry colors.', '2008-03-15 18:46:46.000000', NULL, 1),
(4565862, 656004, 76335, '<td valign="top">Excellent! I love the the contrast between the browns and greens, and the sweeping vertical effect.</td>', 'Excellent! I love the the contrast between the browns and greens, and the sweeping vertical effect.', '2008-03-15 18:46:47.000000', NULL, 1),
(4565863, 657105, 76335, '<td valign="top">I like the radial blur and interesting colors.</td>', 'I like the radial blur and interesting colors.', '2008-03-15 18:46:52.000000', NULL, 1),
(4565864, 657092, 76335, '<td valign="top">Great colors and nicely processed.</td>', 'Great colors and nicely processed.', '2008-03-15 18:47:29.000000', NULL, 1),
(4565865, 654925, 76335, '<td valign="top">This one of the best I''ve seen in a while. Great patterns and colors, and it leaves something to the imagination.</td>', 'This one of the best I''ve seen in a while. Great patterns and colors, and it leaves something to the imagination.', '2008-03-15 18:47:34.000000', NULL, 1),
(4565866, 657135, 76335, '<td valign="top">The colors are awesome. Really. Nice blur effect too.</td>', 'The colors are awesome. Really. Nice blur effect too.', '2008-03-15 18:47:38.000000', NULL, 1),
(4565867, 655721, 76335, '<td valign="top">Looks like a painting. I''m curious to see how you achieved this effect. Great colors here.</td>', 'Looks like a painting. I''m curious to see how you achieved this effect. Great colors here.', '2008-03-15 18:47:40.000000', NULL, 1),
(4565868, 656546, 76335, '<td valign="top">That''s insane. Wow. Looks like the camera was being automatically agitated somehow. Curious to see how you did this. Well done.</td>', 'That''s insane. Wow. Looks like the camera was being automatically agitated somehow. Curious to see how you did this. Well done.', '2008-03-15 18:47:43.000000', NULL, 1),
(4565869, 656358, 76335, '<td valign="top">This is just terrific. Artisitc and chaotic (and blurry in the right places) but still intriguing. Nice work!</td>', 'This is just terrific. Artisitc and chaotic (and blurry in the right places) but still intriguing. Nice work!', '2008-03-15 18:48:33.000000', NULL, 1),
(4565870, 656469, 76335, '<td valign="top">This is terrific! I''ll be excited to read about how you did this.</td>', 'This is terrific! I''ll be excited to read about how you did this.', '2008-03-15 18:48:35.000000', NULL, 1),
(4565871, 656548, 76335, '<td valign="top">This looks like a top ten. Nice job!</td>', 'This looks like a top ten. Nice job!', '2008-03-15 18:48:39.000000', NULL, 1),
(4565872, 655351, 76335, '<td valign="top">Nice artistic processing. Chaotic and blurry too.</td>', 'Nice artistic processing. Chaotic and blurry too.', '2008-03-15 18:49:10.000000', NULL, 1),
(4565874, 657114, 76335, '<td valign="top">Blazing and brilliant. Good use of negative space. I don''t know that the border adds much.</td>', 'Blazing and brilliant. Good use of negative space. I don''t know that the border adds much.', '2008-03-15 18:51:09.000000', NULL, 1),
(4565875, 656054, 76335, '<td valign="top">Good! I was hoping to see more images like this. Very artistic.</td>', 'Good! I was hoping to see more images like this. Very artistic.', '2008-03-15 18:51:13.000000', NULL, 1),
(4565877, 657094, 76335, '<td valign="top">Chaotic with interesting lighting and colros. Nice job!</td>', 'Chaotic with interesting lighting and colros. Nice job!', '2008-03-15 18:51:34.000000', NULL, 1),
(4565878, 656166, 76335, '<td valign="top">Nice textures and lighting.</td>', 'Nice textures and lighting.', '2008-03-15 18:51:46.000000', NULL, 1),
(4565879, 657021, 76335, '<td valign="top">Dreamy with interesting textures. I like the overlapping circles.</td>', 'Dreamy with interesting textures. I like the overlapping circles.', '2008-03-15 18:52:31.000000', NULL, 1),
(4565880, 655773, 76335, '<td valign="top">Very nice! I like the way the light is more about movement and energy than just light. (That probably made about as much sense as this challenge.)</td>', 'Very nice! I like the way the light is more about movement and energy than just light. (That probably made about as much sense as this challenge.)', '2008-03-15 18:52:33.000000', NULL, 1),
(4565881, 656099, 76335, '<td valign="top">Well, this made me laugh. Blurry -- too blurry to be terribly messy. But whatever. Nice job!</td>', 'Well, this made me laugh. Blurry -- too blurry to be terribly messy. But whatever. Nice job!', '2008-03-15 18:52:45.000000', NULL, 1),
(4565882, 656815, 76335, '<td valign="top">You''ve captured a sleepy, drunken effect rather well. I like ths shadows too.</td>', 'You''ve captured a sleepy, drunken effect rather well. I like ths shadows too.', '2008-03-15 18:53:49.000000', NULL, 1),
(4565883, 657119, 76335, '<td valign="top">Leaves a lot to the imagination. Nice job.</td>', 'Leaves a lot to the imagination. Nice job.', '2008-03-15 18:53:55.000000', NULL, 1),
(4565885, 656761, 76335, '<td valign="top">Creative. I think it will be lost on most voters. I had to spend some time with it to "get it" (the title helped though).</td>', 'Creative. I think it will be lost on most voters. I had to spend some time with it to "get it" (the title helped though).', '2008-03-15 18:54:44.000000', NULL, 1),
(4565886, 657132, 76335, '<td valign="top">Very artistic. I like the excellent warm brown tones here.</td>', 'Very artistic. I like the excellent warm brown tones here.', '2008-03-15 18:55:32.000000', NULL, 1),
(4565888, 655018, 76335, '<td valign="top">This is very good. You can almost hear the music, as the photo has a nice rhythm to it.</td>', 'This is very good. You can almost hear the music, as the photo has a nice rhythm to it.', '2008-03-15 18:56:14.000000', NULL, 1),
(4565891, 656888, 76335, '<td valign="top">I like the brilliant colors and patterns here. I''ll be curious to learn what this is.</td>', 'I like the brilliant colors and patterns here. I''ll be curious to learn what this is.', '2008-03-15 18:57:51.000000', NULL, 1),
(4565895, 656371, 76335, '<td valign="top">Nice rhythm and patterns here, and I like the contrast between the light and the background.</td>', 'Nice rhythm and patterns here, and I like the contrast between the light and the background.', '2008-03-15 18:59:59.000000', NULL, 1),
(4565896, 657123, 76335, '<td valign="top">I''m scoring this higher than some others, not because it''s blurry or messy (it''s neither) but just because it''s a really neat photo.</td>', 'I''m scoring this higher than some others, not because it''s blurry or messy (it''s neither) but just because it''s a really neat photo.', '2008-03-15 19:00:02.000000', NULL, 1),
(4565899, 656498, 76335, '<td valign="top">Nice effect. The tree on the left looks surreal -- alive even. The colors are a bit drab though.</td>', 'Nice effect. The tree on the left looks surreal -- alive even. The colors are a bit drab though.', '2008-03-15 19:00:56.000000', NULL, 1),
(4565900, 656207, 76335, '<td valign="top">Brilliant and nicely processed. Good geometry too with the horizontal and vertical lines.</td>', 'Brilliant and nicely processed. Good geometry too with the horizontal and vertical lines.', '2008-03-15 19:01:41.000000', NULL, 1),
(4565901, 655583, 22874, '<td valign="top">you can feel the movement....</td>', 'you can feel the movement....', '2008-03-15 19:01:45.000000', NULL, 1),
(4565903, 656087, 76335, '<td valign="top">Great colors here and nicely processed. Definitely colors you''d see in a party store.</td>', 'Great colors here and nicely processed. Definitely colors you''d see in a party store.', '2008-03-15 19:02:39.000000', NULL, 1),
(4565906, 657046, 76335, '<td valign="top">Chaotic and blurry too. I like the purple and green together. This has a very psychadelic feel to it.</td>', 'Chaotic and blurry too. I like the purple and green together. This has a very psychadelic feel to it.', '2008-03-15 19:03:35.000000', NULL, 1),
(4565907, 657045, 22874, '<td valign="top">love the composition, but it doesn''t meet the definition of blurry</td>', 'love the composition, but it doesn''t meet the definition of blurry', '2008-03-15 19:03:50.000000', NULL, 1),
(4565908, 655628, 76335, '<td valign="top">Nice lighting and textures.</td>', 'Nice lighting and textures.', '2008-03-15 19:04:10.000000', NULL, 1),
(4565914, 657110, 76335, '<td valign="top">Great colors here -- it certainly does flow as the title suggests.</td>', 'Great colors here -- it certainly does flow as the title suggests.', '2008-03-15 19:05:15.000000', NULL, 1),
(4565915, 655997, 76335, '<td valign="top">I''m not sure I get the title, but I like the colors and subtle geometry.</td>', 'I''m not sure I get the title, but I like the colors and subtle geometry.', '2008-03-15 19:05:54.000000', NULL, 1),
(4565916, 656084, 76335, '<td valign="top">This is good and meets the challenge well. I might have cropped out the lower right, as it doesn''t add anything to the image -- in fact the purple distracts from the otherwise intersting effect.</td>', 'This is good and meets the challenge well. I might have cropped out the lower right, as it doesn''t add anything to the image -- in fact the purple distracts from the otherwise intersting effect.', '2008-03-15 19:05:57.000000', NULL, 1),
(4565918, 656059, 76335, '<td valign="top">Simple but very effective. I love the blue tones, and the orange beams of light add some needed interest and contrast.</td>', 'Simple but very effective. I love the blue tones, and the orange beams of light add some needed interest and contrast.', '2008-03-15 19:06:01.000000', NULL, 1),
(4565919, 655494, 76335, '<td valign="top">Nice radial blur captured here, and great colors too.</td>', 'Nice radial blur captured here, and great colors too.', '2008-03-15 19:06:44.000000', NULL, 1),
(4565920, 656685, 76335, '<td valign="top">Bold, noisy and overdone -- so you''ve achieved "messy". Blurry enough too. I like the pattern. Nice work!</td>', 'Bold, noisy and overdone -- so you''ve achieved "messy". Blurry enough too. I like the pattern. Nice work!', '2008-03-15 19:06:46.000000', NULL, 1),
(4565921, 655921, 76335, '<td valign="top">Intriguing. Blurry and chaotic, but a but noisy. Maybe that was intentional. It''s hard to know in this challenge.</td>', 'Intriguing. Blurry and chaotic, but a but noisy. Maybe that was intentional. It''s hard to know in this challenge.', '2008-03-15 19:07:26.000000', NULL, 1),
(4565923, 656985, 76335, '<td valign="top">Simple, yet very effective, the way the threads (?) go in and out of focus.</td>', 'Simple, yet very effective, the way the threads (?) go in and out of focus.', '2008-03-15 19:08:02.000000', NULL, 1),
(4565926, 656762, 76335, '<td valign="top">I can''t see the penguin. Maybe I''m too close. Very artistic though, and nicely processed.</td>', 'I can''t see the penguin. Maybe I''m too close. Very artistic though, and nicely processed.', '2008-03-15 19:08:42.000000', NULL, 1),
(4565928, 655430, 76335, '<td valign="top">The scratches and use of light to bring them out really makes this image work. Black-and-white was a good choice. Nice job!</td>', 'The scratches and use of light to bring them out really makes this image work. Black-and-white was a good choice. Nice job!', '2008-03-15 19:09:35.000000', NULL, 1),
(4565929, 655840, 76335, '<td valign="top">Great framing and nice effect. The title helps.</td>', 'Great framing and nice effect. The title helps.', '2008-03-15 19:09:40.000000', NULL, 1),
(4565930, 657102, 76335, '<td valign="top">Good capture of motion and a nice black-and-white.</td>', 'Good capture of motion and a nice black-and-white.', '2008-03-15 19:10:15.000000', NULL, 1),
(4565931, 656947, 76335, '<td valign="top">Great title, nice effect. The mouth is absolutely gruesome.</td>', 'Great title, nice effect. The mouth is absolutely gruesome.', '2008-03-15 19:10:18.000000', NULL, 1),
(4565934, 656908, 76335, '<td valign="top">They certianly look otherworldly. Nice job processing this. I''m glad you kept (or added) the noise.</td>', 'They certianly look otherworldly. Nice job processing this. I''m glad you kept (or added) the noise.', '2008-03-15 19:11:01.000000', NULL, 1),
(4565935, 657113, 76335, '<td valign="top">I love the grainy effect achieved here.</td>', 'I love the grainy effect achieved here.', '2008-03-15 19:11:07.000000', NULL, 1),
(4565936, 655946, 76335, '<td valign="top">Should have focused more on the ride. I almost missed it! Great effect.</td>', 'Should have focused more on the ride. I almost missed it! Great effect.', '2008-03-15 19:11:09.000000', NULL, 1),
(4565941, 655642, 76335, '<td valign="top">This is stunning. Chaotic for sure, but the colors are brilliant and attractive.</td>', 'This is stunning. Chaotic for sure, but the colors are brilliant and attractive.', '2008-03-15 19:12:43.000000', NULL, 1),
(4565942, 655603, 76335, '<td valign="top">Holy Cripe! Looks like an awful ride whatever it is. Nice job!</td>', 'Holy Cripe! Looks like an awful ride whatever it is. Nice job!', '2008-03-15 19:12:46.000000', NULL, 1),
(4565943, 657095, 76335, '<td valign="top">I like the radial blur effect, and the dreamy, psychadelic feel of it.</td>', 'I like the radial blur effect, and the dreamy, psychadelic feel of it.', '2008-03-15 19:12:49.000000', NULL, 1),
