(4566837, 656544, 76335, '<td valign="top">Excellent idea and well captured.</td>', 'Excellent idea and well captured.', '2008-03-16 00:47:24.000000', NULL, 1),
(4566838, 657063, 89774, '<td valign="top">Reminds me of a colored pencil drawing. You nailed the challenge in my books. Love it, love it, love it!</td>', 'Reminds me of a colored pencil drawing. You nailed the challenge in my books. Love it, love it, love it!', '2008-03-16 00:47:40.000000', NULL, 1),
(4566839, 657141, 89774, '<td valign="top">Absolutely love it!</td>', 'Absolutely love it!', '2008-03-16 00:47:48.000000', NULL, 1),
