(4566857, 656607, 76335, '<td valign="top">Interesting. Not sure what it is; I might help sustain interest if I knew. The colors and patterns alone don''t really make the image.</td>', 'Interesting. Not sure what it is; I might help sustain interest if I knew. The colors and patterns alone don''t really make the image.', '2008-03-16 00:53:28.000000', NULL, 1),
(4566903, 656087, 70514, '<td valign="top">Lovely colorful abstract image.</td>', 'Lovely colorful abstract image.', '2008-03-16 01:49:06.000000', NULL, 1),
(4566904, 655495, 70514, '<td valign="top">I can''t put my finger on exactly what it is, but I find this quite pleasing.</td>', 'I can''t put my finger on exactly what it is, but I find this quite pleasing.', '2008-03-16 01:49:50.000000', NULL, 1),
(4566905, 656480, 70514, '<td valign="top">I like the flowing and soft red color, but the smidge of border at the top and bottom is a bit distracting to me.</td>', 'I like the flowing and soft red color, but the smidge of border at the top and bottom is a bit distracting to me.', '2008-03-16 01:50:25.000000', NULL, 1),
(4566906, 655470, 70514, '<td valign="top">I like everything except the yellow coming closer to me than the other ribbons.  Nicely done otherwise though.</td>', 'I like everything except the yellow coming closer to me than the other ribbons.  Nicely done otherwise though.', '2008-03-16 01:51:06.000000', NULL, 1),
(4566908, 656563, 70514, '<td valign="top">Very funny idea that is well executed.  I just find the overall yellow color a bit of a turn off.</td>', 'Very funny idea that is well executed.  I just find the overall yellow color a bit of a turn off.', '2008-03-16 01:51:53.000000', NULL, 1),
(4566909, 655351, 70514, '<td valign="top">Great processing.  I really like the compositon and subtle blur.</td>', 'Great processing.  I really like the compositon and subtle blur.', '2008-03-16 01:55:38.000000', NULL, 1),
(4566911, 656797, 70514, '<td valign="top">Quite beautiful and serene.  The blues and soft movement of something so powerful strangely provides a feeling of comfort.  Very nicely done.</td>', 'Quite beautiful and serene.  The blues and soft movement of something so powerful strangely provides a feeling of comfort.  Very nicely done.', '2008-03-16 01:56:55.000000', NULL, 1),
(4566913, 656463, 70514, '<td valign="top">An absolutely beautiful moment captured.  Lovely processing to enhance such a lovely memory.</td>', 'An absolutely beautiful moment captured.  Lovely processing to enhance such a lovely memory.', '2008-03-16 01:58:40.000000', NULL, 1),
(4566918, 657074, 70514, '<td valign="top">I really like the idea of this, but it seems slightly tilted.</td>', 'I really like the idea of this, but it seems slightly tilted.', '2008-03-16 02:08:08.000000', NULL, 1),
(4566919, 656860, 70514, '<td valign="top">I wish the head were better observed to match up with the body. It seems to have gotten lost in the water some.  Still a nice idea with pleasant blur.</td>', 'I wish the head were better observed to match up with the body. It seems to have gotten lost in the water some.  Still a nice idea with pleasant blur.', '2008-03-16 02:09:04.000000', NULL, 1),
(4566921, 655757, 70514, '<td valign="top">It''s only ever a child that you see never being too cold to play outside.  I love the snow you captured and maintained, lovely colors, and nice smile (or so it appears).  A lovely picture of childhood captured.</td>', 'It''s only ever a child that you see never being too cold to play outside.  I love the snow you captured and maintained, lovely colors, and nice smile (or so it appears).  A lovely picture of childhood captured.', '2008-03-16 02:12:38.000000', NULL, 1),
(4566923, 656798, 70514, '<td valign="top">I love the red and white contrasting against each other.  Lovely composition.</td>', 'I love the red and white contrasting against each other.  Lovely composition.', '2008-03-16 02:16:22.000000', NULL, 1),
(4566956, 656174, 15711, '<td valign="top">Love that.</td>', 'Love that.', '2008-03-16 03:43:14.000000', NULL, 1),
(4566964, 655603, 58272, '<td valign="top">This creates a great eery effect. Nice Work!</td>', 'This creates a great eery effect. Nice Work!', '2008-03-16 05:07:43.000000', NULL, 1),
(4566967, 655351, 58272, '<td valign="top">This looks like a painting :). I like the bold colours, too.</td>', 'This looks like a painting :). I like the bold colours, too.', '2008-03-16 05:30:08.000000', NULL, 1),
(4566990, 655470, 70661, '<td valign="top">This was a nice idea with all the colors and textures.</td>', 'This was a nice idea with all the colors and textures.', '2008-03-16 07:04:23.000000', NULL, 1),
(4566992, 655045, 90394, '<td valign="top">Blurry, messy, chaotic refraction, and disorganized elements - and I don''t know what the hell I''m looking at. But it is interesting, and a great entry.</td>', 'Blurry, messy, chaotic refraction, and disorganized elements - and I don''t know what the hell I''m looking at. But it is interesting, and a great entry.', '2008-03-16 07:09:47.000000', NULL, 1);
