(4573034, 656463, 70514, '<td valign="top">How I would love to have this capture of my children hanging on my wall.  I love the essence of this entire image.</td>', 'How I would love to have this capture of my children hanging on my wall.  I love the essence of this entire image.', '2008-03-19 03:38:42.000000', NULL, 0),
(4573037, 656159, 70514, '<td valign="top">Not that it matters, but I loved the ethereal feel of this, the blur added a lovely dreamlike quality.  Still one of my fav''s from this challenge.  Wish I had taken it.</td>', 'Not that it matters, but I loved the ethereal feel of this, the blur added a lovely dreamlike quality.  Still one of my fav''s from this challenge.  Wish I had taken it.', '2008-03-19 03:41:04.000000', NULL, 0),
(4573039, 656354, 70514, '<td valign="top">You have such a knack with capturing the pulse of a place, Alicia.  Stunning colors, love the great use of blur without being overbearing.  Just a wonderful integration of all aspects.</td>', 'You have such a knack with capturing the pulse of a place, Alicia.  Stunning colors, love the great use of blur without being overbearing.  Just a wonderful integration of all aspects.', '2008-03-19 03:45:21.000000', NULL, 0),
