(4573265, 657069, 53572, '<td valign="top"><a href="//www.dpchallenge.com/image.php?IMAGE_ID=657243" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/50000-54999/53572/120/657243.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/50000-54999/53572/120/657243.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/50000-54999/53572/120/657243.jpg"/></a> the motion, the intensity, and the viciousness all radiate from the image.  you can hear the growling, snarling and scrabbling on the ground for purchase.</td>', ' the motion, the intensity, and the viciousness all radiate from the image.  you can hear the growling, snarling and scrabbling on the ground for purchase.', '2008-03-19 07:49:59.000000', NULL, 0),
