(4594438, 656783, 62318, '<td valign="top">I really like your outtake, but even your submission was terrific.</td>', 'I really like your outtake, but even your submission was terrific.', '2008-03-28 19:26:29.000000', NULL, 0),
(4595173, 657095, 67697, '<td valign="top">I''m glad that this did better than you expected.  I thought you conveyed the message pretty clearly (it makes you dizzy just looking at it!) and it was a good fit for the theme.</td>', 'I''m glad that this did better than you expected.  I thought you conveyed the message pretty clearly (it makes you dizzy just looking at it!) and it was a good fit for the theme.', '2008-03-29 09:23:31.000000', NULL, 0),
